sys_variable_value.value:
(function execute(inputs, outputs) {

    // Create a new record in the ecc_queue table.
    // var jspr = new global.JavascriptProbe('g3-midserver');
    // jspr.setName('Execute g3 service');
    // jspr.setJavascript("var ddr = new SaveFile(); res= ddr.execute();");
    // jspr.addParameter("verbose","true");
    // jspr.addParameter("service_name", inputs.data.service_name);
    // var eccSysId = jspr.create(); 
    // outputs.ecc_sys_id = eccSysId;

    // Create a new record in the ecc_queue table.
    // Doesn't work as per the below article and the above API should be used.
    // Article - https://www.servicenow.com/community/now-platform-articles/subflow-and-actions-for-saving-file-to-on-premise-network-using/ta-p/2322773
    var gr = new GlideRecord('ecc_queue');
    gr.initialize();
    gr.agent = "mid.server.*";
    gr.queue = "input";
    gr.state = "ready";
    gr.topic = "TriggerG3Service";
    gr.name = inputs.serviceName;
    gr.insert();

    outputs.ecc_sys_id = gr.sys_id;

})(inputs, outputs);

